<?php
require_once __DIR__ . '/../../includes/bootstrap.php';
require_once __DIR__ . '/../includes/admin_auth.php';
if ($_SERVER['REQUEST_METHOD'] !== 'POST' || empty($_SESSION['finance_csrf']) || !hash_equals($_SESSION['finance_csrf'], $_POST['csrf_token'] ?? '')) { $_SESSION['finance_error']='คำขอไม่ถูกต้อง'; header('Location:index.php'); exit; }
$date=trim($_POST['income_date']??''); $source=trim($_POST['source']??''); $description=trim($_POST['description']??''); $amount=(float)($_POST['amount']??0); $d=DateTime::createFromFormat('!Y-m-d',$date);
if(!$d||$d->format('Y-m-d')!==$date||$source===''||$description===''||$amount<=0){$_SESSION['finance_error']='กรุณากรอกข้อมูลรายรับให้ครบถ้วน';header('Location:index.php');exit;}
$savedFile=null; try{if(isset($_FILES['evidence'])&&($_FILES['evidence']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){$file=$_FILES['evidence'];if($file['error']!==UPLOAD_ERR_OK||$file['size']>8*1024*1024)throw new RuntimeException('ไฟล์หลักฐานไม่ถูกต้องหรือมีขนาดเกิน 8 MB');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','application/pdf'=>'pdf'];if(!isset($allowed[$mime]))throw new RuntimeException('รองรับหลักฐานเฉพาะ JPG, PNG, WEBP และ PDF');$dir=__DIR__.'/../../uploads/finance';if(!is_dir($dir)&&!mkdir($dir,0755,true))throw new RuntimeException('ไม่สามารถสร้างโฟลเดอร์หลักฐานได้');$savedFile='income-'.date('YmdHis').'-'.bin2hex(random_bytes(5)).'.'.$allowed[$mime];if(!move_uploaded_file($file['tmp_name'],$dir.'/'.$savedFile))throw new RuntimeException('ไม่สามารถบันทึกไฟล์หลักฐานได้');}$s=$pdo->prepare("INSERT INTO finance_incomes(income_date,source,description,amount,evidence_file,created_by) VALUES(?,?,?,?,?,?)");$s->execute([$date,$source,$description,number_format($amount,2,'.',''),$savedFile,(int)$_SESSION['user_id']]);$id=(int)$pdo->lastInsertId();logAdminAction($pdo,'create','finance_income',$id,'บันทึกรายรับอื่น: '.$source,null,['amount'=>$amount,'income_date'=>$date]);$_SESSION['finance_success']='บันทึกรายรับเพิ่มเติมแล้ว';}catch(Throwable $e){if($savedFile&&is_file(__DIR__.'/../../uploads/finance/'.$savedFile))@unlink(__DIR__.'/../../uploads/finance/'.$savedFile);$_SESSION['finance_error']=$e->getMessage();}header('Location:index.php?month='.rawurlencode(substr($date,0,7)));exit;
